import {language, setLanguage, tr, localize, media, languages} from './i18n.js?v=5';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const preselectionOnly=()=>new URLSearchParams(location.search).get('selection')==='metacritic';
const number=n=>new Intl.NumberFormat(language()).format(n||0);
const paths={bolt:'M13 2 4 14h7l-1 8 10-12h-7l1-8Z',arrow:'M5 12h14m-6-6 6 6-6 6',crown:'m3 6 5 5 4-7 4 7 5-5-2 13H5L3 6Z',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',bracket:'M4 3v6h6V3M4 15v6h6v-6M10 6h6v12h-6m6-6h5',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',share:'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm12 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM8.5 10.5l7-4m-7 7 7 4',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M13 3.1a4 4 0 0 1 0 7.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',search:'m21 21-4.4-4.4M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',close:'m6 6 12 12M6 18 18 6',lock:'M5 11h14v10H5zM8 11V7a4 4 0 0 1 8 0v4',game:'M6 7h12c2 0 3 2 4 10s-4 4-6 0H8c-2 4-7 7-6 0S4 7 6 7Zm0 3v6m-3-3h6m7-1h.1m3 3h.1',external:'M14 3h7v7m0-7L10 14m0-11H3v18h18v-7',shuffle:'m3 4 18 16m-5 0h5v-5M3 20 21 4m-5 0h5v5',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.game}"/></svg>`;
const loadLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let state,route=location.pathname,selectedMatch=route.startsWith('/duel/')?route.split('/')[2]:null;
let favourites=new Set(loadLocal('vgb-favourites',[])),skipped=new Set(),filter='all',query='',sort='seed',bracketTab='upper',gameLimit=48,busy=false,pendingVote=null,adminKey='',authReturn=null;
let gameMap=new Map();
const queueSeed=Math.random();
const queueRank=m=>{let h=0;for(const c of m.id)h=(h*31+c.charCodeAt(0))>>>0;return Math.sin(h+queueSeed*100000);};
const g=id=>gameMap.get(id);
const image=g=>g?.coverLocal||`/covers/${g?.id}.webp`;
const short=t=>t.replace('The Legend of Zelda: ','Zelda: ').replace('The Elder Scrolls V: ','');
const countVotes=()=>Object.keys(state.myVotes).length;
async function api(url,body,extra={}){const response=await fetch(url,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...extra},...(body!==undefined?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Object.assign(new Error(tr(data.code||data.error||'Le serveur ne répond pas.')),{status:response.status});return data;}
async function refresh(renderNow=true){state=await api('/api/state');gameMap=new Map(state.games.map(x=>[x.id,x]));if(renderNow)render();}
function toast(text){$('#toast').textContent=tr(text);$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function navigate(url){history.pushState({},'',url);route=location.pathname;query='';gameLimit=48;if(preselectionOnly())filter='all';selectedMatch=route.startsWith('/duel/')?route.split('/')[2]:null;render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('popstate',()=>{route=location.pathname;selectedMatch=route.startsWith('/duel/')?route.split('/')[2]:null;query='';if(preselectionOnly())filter='all';render();});
function nav(){const active=route.startsWith('/duel/')?'/':route;const links=[['/','bolt','L’arène'],['/poules','grid','Les poules'],['/tableau','bracket','Le tableau'],['/jeux','game','Les jeux'],['/propositions','heart','Propositions']];return `<header class="site-header"><div class="header-inner"><a href="/" data-nav class="logo" aria-label="Video Games Battle, accueil"><span class="brand-mark">V</span><span>VIDEO GAMES<span class="logo-bottom">BATTLE<span class="acid">.</span></span></span></a><nav class="desktop-nav" aria-label="Navigation principale">${links.map(([url,i,name])=>`<a data-nav href="${url}" class="${active===url?'active':''}">${name}</a>`).join('')}</nav><div class="header-right"><select id="language" aria-label="Langue" lang="${language()}">${Object.entries(languages).map(([code,[flag,name]])=>`<option value="${code}" lang="${code}" ${language()===code?'selected':''}>${flag} ${name}</option>`).join('')}</select><a href="/regles" data-nav class="rules-link">Le concept ${icon('external')}</a><button class="btn btn-small ${state.user?'btn-outline':'btn-acid'}" data-action="${state.user?'profile':'login'}">${state.user?icon('check'):icon('users')}<span>${state.user?'Mon parcours':'Rejoindre le tournoi'}</span></button></div></div></header><nav class="mobile-nav" aria-label="Navigation mobile">${links.map(([url,i,name])=>`<a data-nav href="${url}" class="${active===url?'active':''}">${icon(i)}<span>${name}</span></a>`).join('')}<a href="/profil" data-nav class="${active==='/profil'?'active':''}">${icon('heart')}<span>Moi</span></a></nav>`;}
const pressLogo=id=>id?`/assets/media/${id}.png`:'';
function mediaCard(name,url,logo,sponsor=false){
  const hostname=new URL(url).hostname.replace(/^www\./,'');
  return `<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer${sponsor?' sponsored':''}" data-untranslated>
    <span class="media-logo" aria-hidden="true"><span>${esc(Array.from(name.trim()).slice(0,2).join('').toUpperCase())}</span>${logo?`<img src="${esc(logo)}" alt="" loading="lazy">`:''}</span>
    <span class="media-card-label"><strong>${esc(name)}</strong><small>${esc(hostname)}</small></span>${icon('external')}
  </a></li>`;
}
document.addEventListener('error',event=>{
  if(event.target.matches?.('.media-logo img')) event.target.remove();
},true);
function adSlot(){
  const ad=state.ads?.[language()]||state.ads?.fr;
  if(!ad)return '';
  return `<aside class="ad-slot" aria-label="Publicité"><small>Publicité</small>
    <a href="${esc(ad.url)}" rel="sponsored noopener noreferrer" target="_blank" data-untranslated>
      ${ad.logo?`<img src="${esc(ad.logo)}" alt="">`:''}<strong>${esc(ad.name)}</strong>${icon('external')}
    </a></aside>`;
}
function footer(){
  const outlets=media[language()];
  const sponsors=state.sponsors?.[language()]||[];
  return `${sponsors.length?`<section class="media-section container" aria-labelledby="sponsor-title">
    <h2 id="sponsor-title">Sponsors</h2>
    <ul>${sponsors.map(({name,url,logo})=>mediaCard(name,url,logo||pressLogo(outlets.find(([,site])=>new URL(site).hostname===new URL(url).hostname)?.[2]),true)).join('')}</ul>
  </section>`:''}<section class="media-section container" aria-labelledby="media-title">
    <h2 id="media-title">À lire dans la presse jeux vidéo</h2>
    <ul>${outlets.map(([name,url,id])=>mediaCard(name,url,pressLogo(id))).join('')}</ul>
  </section><footer class="footer"><a href="/" class="footer-brand" data-nav>VGB<span class="acid">.</span></a><div><a href="/regles" data-nav>Règles et méthode</a><button class="text-button" data-action="privacy">Confidentialité</button><button class="text-button" data-action="about">À propos</button></div><small>Visuels et marques : leurs ayants droit respectifs.</small></footer>`;
}
const poolMatchCount=()=>state.rules.perGroup*(state.rules.perGroup-1)/2;
const finalistCount=()=>state.rules.groups*state.rules.qualifyPerGroup;
function hero(){
  const picks=[0,4,7].map(i=>state.games[i]);
  return `<section class="hero ${state.phase==='community'?'hero-pending':''}">
    <div class="hero-copy">
      <h1>${language()==='fr'?'Le tournoi des <em>jeux cultes</em>':tr('Le tournoi des jeux cultes')}</h1>
      <p>${state.phase==='community'?'Vote dès maintenant pour les 250 jeux présélectionnés et aide à choisir les six derniers.':'De toutes les générations et de toutes les consoles, 256 jeux s’affrontent. À chaque duel, vote pour celui que tu préfères.'}</p>
      <div class="hero-actions">${state.phase==='community'?`<button class="btn btn-acid" data-action="arena">Voir le duel ${icon('arrow')}</button><a class="how-link" href="/propositions" data-nav>Choisir les six jeux ${icon('arrow')}</a>`:`<button class="btn btn-acid" data-action="arena">Voir le duel ${icon('arrow')}</button>`}<a href="/regles" data-nav class="how-link">Lire les règles ${icon('info')}</a></div>
    </div>
    ${state.phase==='community'?selectionPreview():`<div class="hero-covers" aria-hidden="true">${picks.map(game=>`<img src="${image(game)}" alt="">`).join('')}</div>`}
  </section>
  <div class="tournament-strip">
    <div><strong>256</strong><span>jeux</span></div>
    <div><strong>${state.rules.groups}</strong><span>poules</span></div>
    <div><strong>${finalistCount()}</strong><span>qualifiés</span></div>
    <div><strong>1</strong><span>champion</span></div>
  </div>`;
}
function currentMatch(){if(selectedMatch){const specific=state.matches.find(m=>m.id===selectedMatch);if(specific)return specific;}
  let matches=state.matches.filter(m=>m.status==='open');
  if(filter==='favourites')matches=matches.filter(m=>favourites.has(m.gameA)||favourites.has(m.gameB));
  const candidates=matches.filter(m=>!state.myVotes[m.id]&&!skipped.has(m.id));
  if(filter==='favourites'&&!matches.length)return null;
  candidates.sort((a,b)=>a.total-b.total||queueRank(a)-queueRank(b));
  return candidates[0]||matches.find(m=>!skipped.has(m.id))||matches[0]||state.matches.find(m=>m.status==='closed')||state.matches[0];}
function timeLabel(m){if(m.status==='closed')return 'Duel terminé';if(m.openedAt===null)return 'En attente du lancement';if(m.stage==='pool')return m.quotaReached?'Seuil atteint':'En route vers 10 000 votes';const remaining=m.openedAt+state.rules.minDurationMs-Date.now();if(remaining<=0)return m.total>=10000&&m.votesA===m.votesB?'Égalité · prolongation':'Durée minimale atteinte';return `${Math.ceil(remaining/86400000)} j minimum restants`;}
function gameCard(game,m,side){if(!game)return '';const voted=state.myVotes[m.id],results=m.votesA!==null,own=voted===game.id,percentage=results&&m.total?((side===0?m.votesA:m.votesB)/m.total*100):0;const status=m.status==='closed';return `<article class="battle-card side-${side} ${own?'chosen':''}"><div class="battle-art"><img src="${image(game)}" alt="Jaquette de ${esc(game.title)}" fetchpriority="high"><div class="art-shade"></div><div class="battle-top"><span class="seed">SEED #${game.seed}</span><button class="favorite ${favourites.has(game.id)?'is-favourite':''}" data-action="favourite" data-id="${game.id}" aria-pressed="${favourites.has(game.id)}" aria-label="Suivre ${esc(game.title)}">${icon('heart')}</button></div><div class="battle-title"><span class="platform-tag">${esc(game.platform)} <span>·</span> ${game.year}</span><h3 data-untranslated>${esc(game.title)}</h3>${game.community?'<span class="platform-tag">Choix de la communauté</span>':`<a href="${esc(game.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="metascore"><b>${game.score}</b><span>METASCORE<br><span>Version retenue ${icon('external')}</span></span></a>`}</div></div><div class="battle-vote">${results?`<div class="vote-result"><strong>${percentage.toFixed(1).replace('.',',')}<small>%</small></strong><span>${own?`${icon('check')} TON CHOIX`:status?(!m.winner?'Match nul':m.winner===game.id?'VICTOIRE':'DUEL TERMINÉ'):number(side===0?m.votesA:m.votesB)+' votes'}</span></div><div class="result-track"><i style="width:${percentage}%"></i></div>`:`<button class="btn ${side===0?'btn-acid':'btn-purple'} vote-button" data-action="vote" data-match="${m.id}" data-id="${game.id}" ${m.status!=='open'?'disabled':''}>${icon('bolt')} ${m.status==='open'?'Je vote pour ce jeu':'Ouverture prochaine'} ${icon('arrow')}</button>`}</div></article>`;}
function arena(){const m=currentMatch();if(!m&&!state.matches.length)return '<div class="empty">Aucun duel ouvert pour le moment.</div>';if(!m)return `<div class="empty">Aucun duel ouvert pour tes favoris. Suis des jeux dans le catalogue ou reviens à tous les duels.<br><button class="btn btn-outline" data-action="filter" data-filter="all">Tous les duels</button></div>`;if(m.status==='pending'&&m.stage==='pool')return `<div class="notice">Ce duel s’ouvrira quand le jeu communautaire aura obtenu sa place. <a href="/propositions" data-nav class="text-button acid">Voir les propositions</a></div>`;const seen=state.myVotes[m.id];return `<section class="arena section" id="arena"><div class="section-heading"><div><div class="eyebrow acid">${icon('bolt')} ${state.phase==='complete'?'LES RÉSULTATS':m.status==='open'?'À TOI DE JOUER':'LE TOURNOI'}</div><h2>${seen?'Résultat du duel':'Quel jeu préfères-tu ?'}</h2></div><div class="arena-filters"><button class="chip ${filter==='all'?'active':''}" data-action="filter" data-filter="all">Tous les duels</button><button class="chip ${filter==='favourites'?'active':''}" data-action="filter" data-filter="favourites">${icon('heart')} Mes favoris</button></div></div><div class="match-bar"><span><span class="live-dot ${m.status==='closed'?'muted':''}"></span> ${m.stage==='pool'?`POULE ${String(m.groupId).padStart(2,'0')} <span class="muted-text">/ DUEL ${m.index} SUR ${poolMatchCount()}</span>`:`${m.stage==='upper'?'TABLEAU DES VAINQUEURS':m.stage==='lower'?'TABLEAU DE REPÊCHAGE':'GRANDE FINALE'} · ${m.id}`}</span><button class="text-button" data-action="share" data-match="${m.id}">${icon('share')} Défier un ami</button></div><div class="battle-grid">${gameCard(g(m.gameA),m,0)}<div class="versus"><span>VS</span></div>${gameCard(g(m.gameB),m,1)}</div><div class="match-progress"><div class="vote-goal"><div><span>${icon('users')} <strong>${number(m.total)}</strong> / 10 000 votes</span><span class="${m.total>=10000?'acid':''}">${Math.min(100,m.total/100).toFixed(m.total?1:0).replace('.',',')} %</span></div><div class="progress-track"><i style="width:${Math.min(100,m.total/100)}%"></i></div></div><div class="time-goal">${icon('clock')}<span><strong>${timeLabel(m)}</strong><small>${m.stage==='pool'?'Clôture commune à toutes les poules':'Les deux seuils sont obligatoires'}</small></span></div><button class="btn btn-outline next-btn" data-action="next">${seen?'Duel suivant':'Passer ce duel'} ${icon('arrow')}</button></div><div class="duel-footnote"><span>${icon('lock')} ${seen?'Un vote unique, enregistré pour ce duel.':'Résultats révélés après ton vote. Choisis librement.'}</span>${m.stage==='pool'?'<span>Victoire nette : <b>3 pts</b> · Duel serré : <b>2 / 1 pts</b></span>':'<span>Deux défaites pour être éliminé. Aucun point en phase finale.</span>'}</div>${seen?`<div class="share-nudge"><span>Tu défends <strong>${esc(short(g(seen).title))}</strong>. Tes amis aussi ?</span><button data-action="share" data-match="${m.id}" class="text-button acid">Lancer le débat ${icon('share')}</button><button data-action="card" data-id="${seen}" class="text-button">Ma carte supporter ${icon('download')}</button></div>`:''}</section>`;}
const selectionUrl='/jeux?selection=metacritic';
const selectionLink=()=>`<a href="${selectionUrl}" data-nav class="text-button acid">Voir les 250 jeux présélectionnés ${icon('arrow')}</a>`;
function selectionPreview(){
  return `<section class="selection-preview section" aria-labelledby="selection-preview-title">
    <div class="selection-heading"><h2 id="selection-preview-title">Aperçu des 250 jeux présélectionnés</h2>${selectionLink()}</div>
    <ul>${state.games.filter(game=>game.seed<=250).slice(0,6).map(game=>`<li><button data-action="game" data-id="${game.id}" data-untranslated>
      <img src="${image(game)}" alt="" loading="lazy"><span><strong>${esc(game.title)}</strong><small>${esc(game.platform)} · ${game.year}</small></span>
    </button></li>`).join('')}</ul>
  </section>`;
}
function poolProgress(){
  const matches=state.matches.filter(m=>m.stage==='pool');
  if(!matches.length)return '';
  const groups=Map.groupBy(matches,m=>m.groupId);
  const count=matches.filter(m=>m.quotaReached).length;
  return `<section class="section pool-progress" aria-labelledby="pool-progress-title">
    <div class="selection-heading"><h2 id="pool-progress-title">Progression des duels de poule</h2><strong>${number(count)} / ${number(matches.length)} · ${tr('Seuil atteint')}</strong></div>
    <p>${['community','pools'].includes(state.phase)?'Un cercle orange indique un duel à 10 000 votes. Tu peux continuer à voter jusqu’à ce que tous les cercles soient orange.':'Tous les duels de poule ont atteint le seuil. Les résultats sont définitifs.'}</p>
    <div class="pool-dot-groups">${Array.from(groups,([id,duels])=>`<div class="pool-dot-group">
      <b>${tr('Poule '+id)}</b>
      <div class="pool-dots">${duels.map(m=>`<a data-nav href="/duel/${m.id}" class="pool-dot ${m.quotaReached?'reached':''}" title="${esc((g(m.gameA)?.title||tr('Place communautaire')))} / ${esc((g(m.gameB)?.title||tr('Place communautaire')))} · ${number(m.total)} / ${number(state.rules.minVotes)}"></a>`).join('')}</div>
    </div>`).join('')}</div>
  </section>`;
}
function home(){
  const champion=g(state.champion);
  return `${hero()}${state.phase==='community'?'':selectionPreview()}${champion?`<div class="champion-banner">${icon('crown')}<div><h2>${esc(champion.title)}</h2><p>Champion de la première édition.</p></div></div>`:''}${arena()}${poolProgress()}
    <section class="journey section">
      <div><h2>Le format du tournoi</h2><a href="/regles" data-nav class="text-button acid">Toutes les règles ${icon('arrow')}</a></div>
      <article><h3>Les poules</h3><p>Huit jeux par poule. Chaque jeu affronte les sept autres. Les quatre premiers se qualifient.</p><a href="/poules" data-nav class="text-button">Voir les poules ${icon('arrow')}</a></article>
      <article><h3>La double élimination</h3><p>Les 128 qualifiés ont droit à une seconde chance. La deuxième défaite les élimine.</p><a href="/tableau" data-nav class="text-button">Voir le tableau ${icon('arrow')}</a></article>
      <article><h3>La grande finale</h3><p>Le vainqueur du tableau principal affronte celui du repêchage.</p></article>
    </section>`;
}
function heading(kicker,title,subtitle){return `<div class="page-heading">${kicker?`<div class="eyebrow acid">${kicker}</div>`:''}<h1>${title}</h1><p>${subtitle}</p></div>`;}
const search=(placeholder)=>`<div class="search-box">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(query)}"></div>`;
function pools(){
  const {groups,perGroup,qualifyPerGroup}=state.rules;
  const duels=poolMatchCount();
  const list=state.groups.filter(p=>!query||String(p.id)===query||p.rows.some(r=>g(r.gameId).title.toLowerCase().includes(query.toLowerCase())));
  return `${heading('PHASE DE POULES','Les poules',`${perGroup} jeux par poule. Les ${qualifyPerGroup} premiers passent en phase finale.`)}
  <div class="page-toolbar">${search('Trouver un jeu ou une poule…')}<span>${state.groups.filter(p=>p.ready).length} / ${groups} poules au seuil</span><button class="text-button" data-action="seeding">Répartition des jeux ${icon('info')}</button></div>
  <div class="notice compact">${icon('info')} En cas d’égalité de points en fin de poule, le total des voix sur les sept duels départage les jeux.</div>
  <div class="pool-grid">${list.map(p=>`<article class="pool-card">
    <div class="pool-heading"><h2>Poule ${String(p.id).padStart(2,'0')}</h2><span>${p.complete?'Terminée':p.reached+'/'+duels+' au seuil'}</span></div>
    <div class="table-head"><span>Jeu</span><span title="Duels joués">J</span><span title="Points">Pts</span><span>Voix</span></div>
    ${p.rows.map((r,i)=>{
      const game=g(r.gameId);
      const qualified=p.ready&&i<qualifyPerGroup;
      return `<div class="pool-row ${qualified?'qualified':''}">
        <span class="pool-position" aria-label="${i+1}${qualified?' · qualifié':''}">${i+1}</span><img src="${image(game)}" alt="" loading="lazy">
        <div><strong data-untranslated>${esc(game.title)}</strong><small>${qualified?(p.complete?'Qualifié · ':'Provisoire · '):''}#${r.seed} · ${esc(game.platform)}</small></div>
        <span>${r.played}</span><b>${r.points}</b><span class="pool-votes">${number(r.totalVotes)}</span>
      </div>`;
    }).join('')}
    <button class="pool-link" data-action="group" data-id="${p.id}">${p.complete?'Voir les résultats':`Voir les ${duels} duels`} ${icon('arrow')}</button>
  </article>`).join('')}</div>${list.length?'':'<div class="empty">Aucune poule pour cette recherche.</div>'}`;
}
function bracketPlaceholder(){
  const list=[];
  const size=finalistCount();
  const upperRounds=Math.log2(size);
  for(let r=1;r<=upperRounds;r++)for(let i=1;i<=size/2**r;i++)list.push({id:`W${r}-${i}`,stage:'upper',round:r,status:'pending'});
  for(let r=1;r<=2*(upperRounds-1);r++)for(let i=1;i<=size/2**(Math.ceil(r/2)+1);i++)list.push({id:`L${r}-${i}`,stage:'lower',round:r,status:'pending'});
  for(let r=1;r<=2;r++)list.push({id:`GF-${r}`,stage:'final',round:r,status:'pending'});
  return list;
}
function bracket(){let all=state.matches.filter(m=>m.stage!=='pool');if(!all.length){
  const preview=new Map(state.provisionalMatches.map(m=>[m.id,m]));
  all=bracketPlaceholder().map(m=>preview.has(m.id)?{...m,...preview.get(m.id),provisional:true}:m);
}const selected=all.filter(m=>m.stage===bracketTab);const rounds=[...new Set(selected.map(m=>m.round))];return `${heading('PHASE 02 · DOUBLE ÉLIMINATION','Le tableau',`${finalistCount()} qualifiés. Un jeu est éliminé après sa deuxième défaite.`)}<div class="page-toolbar"><div class="tabs">${[['upper','Vainqueurs'],['lower','Repêchage'],['final','Grande finale']].map(([id,t])=>`<button class="${bracketTab===id?'active':''}" data-action="bracket-tab" data-id="${id}">${t}</button>`).join('')}</div><span>${state.qualified.length||state.provisional.length} / ${finalistCount()} ${['community','pools'].includes(state.phase)?'qualifiés provisoires':'qualifiés'}</span></div>${state.qualified.length?'':`<div class="notice">${icon('lock')} Dès que tous les duels d’une poule atteignent 10 000 votes, ses quatre premiers apparaissent ici. Les jeux et leur placement restent provisoires jusqu’à la clôture de toutes les poules. Les votes continuent entre-temps.</div>`}<div class="bracket-scroll" tabindex="0" aria-label="Tableau à faire défiler horizontalement"><div class="bracket-grid ${bracketTab==='final'?'final-rounds':''}">${rounds.map(r=>`<section class="bracket-round"><div class="round-title">${bracketTab==='upper'?(r===rounds.at(-1)?'FINALE VAINQUEURS':'TOUR '+r):bracketTab==='lower'?(r===rounds.at(-1)?'FINALE REPÊCHAGE':'TOUR '+r):r===1?'LA GRANDE FINALE':'FINALE DÉCISIVE'}<small>${bracketTab==='final'&&r===2?'Si le finaliste repêché gagne':'14 jours + 10 000 votes / duel'}</small></div><div class="bracket-matches">${selected.filter(m=>m.round===r).map(m=>`<button class="bracket-match ${m.status==='closed'?'done':''}" data-action="${m.gameA&&!m.provisional?'open-match':'bracket-info'}" data-id="${m.id}"><span class="bracket-id">${m.id}<span>${m.provisional&&(m.gameA||m.gameB)?'PROVISOIRE':m.status==='open'?'● VOTE OUVERT':m.status==='closed'?'TERMINÉ':m.status==='cancelled'?'NON NÉCESSAIRE':'À VENIR'}</span></span>${[m.gameA,m.gameB].map((id,i)=>`<span class="bracket-team ${m.winner===id&&id?'winner':''}">${id?`<img src="${image(g(id))}" alt="" loading="lazy"><strong>${esc(short(g(id).title))}</strong><small>#${g(id).seed}</small>`:`<span class="slot-icon">${icon(bracketTab==='final'?'crown':'game')}</span><span>${bracketTab==='final'?i===0?'Champion des vainqueurs':'Champion du repêchage':r===1&&bracketTab==='upper'?'Qualifié de poule':'À déterminer'}</span>`}</span>`).join('')}</button>`).join('')}</div></section>`).join('')}</div></div><div class="notice">${icon('info')} Les points 3/0 et 2/1 concernent les poules. En phase finale, toute majorité fait avancer le vainqueur. Une égalité exacte prolonge le duel.</div>`;}
function nominations(){
  const {candidates,selected,slots}=state.nominations;
  const open=state.phase==='community'&&selected.length<slots;
  const supported=candidates.filter(game=>game.supported).length;
  return `${heading('', 'Les choix de la communauté','Les six premiers jeux à dépasser 2 500 votes rejoignent les 250 jeux présélectionnés. Une place acquise est définitive.')}
    <div class="selection-note"><span>Vérifie la liste avant de proposer un jeu.</span> ${selectionLink()}</div>
    ${open?(state.user?`<form id="nomination-form" class="nomination-form">
      <h2>Proposer un jeu</h2>
      <label>Titre <input name="title" required maxlength="120"></label>
      <label>Plateforme <input name="platform" required maxlength="60"></label>
      <label>Année de sortie <input name="year" type="number" required min="1950" max="${new Date().getFullYear()}"></label>
      <button class="btn btn-acid">Ajouter la proposition</button>
      <p class="form-error" role="alert"></p>
    </form>`:`<div class="notice">Connecte-toi pour proposer un jeu et soutenir jusqu’à six titres. <button class="btn btn-acid" data-action="login">Me connecter</button></div>`):
      '<div class="notice">La sélection communautaire est terminée.</div>'}
    <div class="nomination-heading"><h2>Les propositions</h2><strong>${selected.length} / ${slots} ${tr('places attribuées')}</strong>${open&&state.user?`<span>${supported} / ${slots} soutiens utilisés</span>`:''}</div>
    ${candidates.length?`<ol class="nomination-list">${candidates.map(game=>`<li>
      <div><strong data-untranslated>${esc(game.title)}</strong><small data-untranslated>${esc(game.platform)} · ${game.year}</small></div>
      <span>${number(game.votes)} / ${number(state.rules.nominationVotes)} votes</span>
      ${selected.includes(game.id)?'<b class="acid">Retenu</b>':open?`<button class="btn btn-small ${game.supported?'btn-outline':'btn-acid'}" data-action="support-nomination" data-id="${game.id}" data-support="${!game.supported}" aria-pressed="${!!game.supported}">${game.supported?'Retirer mon soutien':'Soutenir'}</button>`:''}
    </li>`).join('')}</ol>`:'<div class="empty">Aucune proposition pour le moment.</div>'}`;
}
function catalogue(){const preselected=preselectionOnly();let games=state.games.filter(x=>(!preselected||x.seed<=250)&&(!query||`${x.title} ${x.platform} ${x.year}`.toLowerCase().includes(query.toLowerCase()))&&(filter!=='saved'||favourites.has(x.id)));if(sort==='year')games.sort((a,b)=>b.year-a.year);if(sort==='alpha')games.sort((a,b)=>a.title.localeCompare(b.title,language()));return `${heading('',preselected?'Sélection Metacritic':'Les jeux','Les 250 premiers jeux sont sélectionnés selon leur Metascore. Six places sont réservées à la communauté.')}<div class="page-toolbar catalogue-toolbar">${preselected?'<a href="/jeux" data-nav class="text-button acid">Tous les jeux</a>':''}${search('Un jeu, une plateforme, une année…')}<button class="chip ${filter==='saved'?'active':''}" data-action="catalogue-favourites">${icon('heart')} Mes favoris (${favourites.size})</button><select id="sort" aria-label="Trier les jeux"><option value="seed" ${sort==='seed'?'selected':''}>Meilleur Metascore</option><option value="year" ${sort==='year'?'selected':''}>Plus récents</option><option value="alpha" ${sort==='alpha'?'selected':''}>Ordre alphabétique</option></select></div><div class="catalogue-caption"><span>${games.length} jeux · Données vérifiées le 11 novembre 2026</span><a href="/regles#selection" data-nav>La méthode de sélection ${icon('external')}</a></div><div class="game-grid">${(preselected?games:games.slice(0,gameLimit)).map(game=>`<article class="game-tile"><div class="game-poster"><button class="poster-link" data-action="game" data-id="${game.id}" aria-label="Voir ${esc(game.title)}"><img src="${image(game)}" alt="Jaquette de ${esc(game.title)}" loading="lazy"></button><span class="tile-seed">#${game.seed}</span><span class="tile-score">${game.community?'Communauté':game.score}</span><button class="favorite ${favourites.has(game.id)?'is-favourite':''}" data-action="favourite" data-id="${game.id}" aria-pressed="${favourites.has(game.id)}" aria-label="Suivre ${esc(game.title)}">${icon('heart')}</button></div><button class="game-title" data-untranslated data-action="game" data-id="${game.id}">${esc(game.title)}</button><p>${esc(game.platform)} <span>·</span> ${game.year}</p></article>`).join('')}</div>${!preselected&&games.length>gameLimit?'<div class="center"><button class="btn btn-outline" data-action="more">Voir plus de légendes '+icon('arrow')+'</button></div>':''}${games.length?'':'<div class="empty">Aucun jeu trouvé. Essaie un autre titre.</div>'}`;}
function rules(){return `${heading('LES RÈGLES DU JEU','Une couronne. Des règles claires.','La sélection vient des critiques. Le verdict appartient aux votants.')}<div class="rules-layout"><aside class="rules-menu"><a href="#format">01 · Le format</a><a href="#points">02 · Les points</a><a href="#seuils">03 · La clôture</a><a href="#finale">04 · La double élimination</a><a href="#selection">05 · La sélection</a><a href="#equite">06 · L’équité</a></aside><div class="rules-content"><section id="format"><span class="eyebrow acid">01 · LE FORMAT</span><h2>256 jeux, 32 poules, 128 qualifiés</h2><p>Les huit jeux de chaque poule s’affrontent deux à deux, pour un total de 28 duels. Les quatre premiers rejoignent la phase finale. Les duels entre jeux présélectionnés s’ouvrent immédiatement. Chaque jeu communautaire ouvre ses sept duels dès qu’il obtient sa place.</p><p>Le placement en serpentin répartit les têtes de série. Chaque poule reçoit un jeu de chacune des huit tranches de 32 places du classement initial.</p><div class="rules-callout">896 duels de poule × 10 000 votes = <strong>8 960 000 votes minimum</strong> avant la phase finale. Un joueur peut voter sur tous les duels, une fois par duel.</div></section><section id="points"><span class="eyebrow acid">02 · LES POINTS</span><h2>Chaque victoire compte. Sa marge aussi.</h2><div class="points-grid"><div><strong>3 <span>/ 0</span></strong><h3>Victoire nette</h3><p>Le vainqueur obtient strictement plus de 55 % des votes.</p></div><div><strong>2 <span>/ 1</span></strong><h3>Duel serré</h3><p>Le vainqueur obtient plus de 50 % et au maximum 55 %. La borne 55 % est incluse.</p></div></div><p>En poule, un duel à égalité à la clôture donne zéro point aux deux jeux. En phase finale, un 50/50 prolonge le vote.</p><p>Une fois les 28 duels de la poule terminés, les jeux à égalité de points sont départagés par le nombre total de voix reçues sur leurs sept duels. Si ce total est identique, le meilleur rang initial l’emporte.</p></section><section id="seuils"><span class="eyebrow acid">03 · LA CLÔTURE</span><h2>Quand les votes se terminent</h2><p>En poule, chaque duel atteint son seuil à 10 000 votes. Tous restent ouverts jusqu’à ce que le dernier duel atteigne ce seuil. Les résultats sont alors figés ensemble, sans durée minimale. En phase finale, chaque duel exige toujours 14 jours, 10 000 votes et une majorité.</p><p>Les quatre premiers d’une poule apparaissent dans le tableau provisoire dès que ses 28 duels ont atteint le seuil. De nouveaux votes peuvent encore changer les qualifiés et leur placement jusqu’à la clôture commune.</p></section><section id="finale"><span class="eyebrow acid">04 · LA DOUBLE ÉLIMINATION</span><h2>Tomber une fois. Revenir plus fort.</h2><p>Les 128 qualifiés sont classés selon leur seed initial. Le tableau des vainqueurs suit le placement standard 1 contre 128, 2 contre 127, etc., réparti pour séparer les meilleures têtes de série.</p><p>Une première défaite envoie dans le tableau de repêchage. Une seconde élimine le jeu. En phase finale, les points disparaissent : une majorité, même 50,01 %, suffit pour gagner une fois les deux seuils atteints.</p><p>La grande finale oppose les gagnants des deux tableaux. Si le finaliste repêché gagne, il inflige la première défaite à l’autre finaliste : <strong>une seconde finale décisive est alors organisée</strong>, avec à nouveau 14 jours et 10 000 votes minimum.</p><div class="rules-callout">254 duels de phase finale, ou 255 avec seconde finale. Total minimum de l’édition : <strong>11,50 millions de votes</strong> (11,51 millions avec seconde finale).</div><p>Après les poules, la phase finale dure au moins 196 jours, ou 210 jours avec seconde finale, si chaque duel atteint son quota dès le quatorzième jour.</p></section><section id="selection"><span class="eyebrow acid">05 · LA SÉLECTION</span><h2>Un jeu, une place.</h2><p>Les 250 jeux présélectionnés viennent du catalogue de Metacritic. Les six autres sont choisis sur la page <a class="acid" href="/propositions" data-nav>Propositions</a> avant le lancement du tournoi. Le Metascore est la note agrégée des critiques, pas la note des utilisateurs. Pour chaque famille de jeu, la version et la plateforme au Metascore le plus élevé sont retenues. L’année affichée correspond à cette version.</p><p>Ports, remasters, remakes et éditions enrichies sont regroupés. Les vraies suites restent distinctes. Les compilations multi-jeux et les extensions dépendantes sont exclues pour éviter de compter plusieurs fois les mêmes jeux. Les plateformes mobiles sont incluses.</p><p>Les scores identiques sont départagés par le nombre de critiques de la version, puis par la date de sortie de la version, le titre et la plateforme. Certaines versions reposent sur seulement quatre à six critiques ; ce nombre est indiqué sur leur fiche. Ces choix éditoriaux sont détaillés dans le fichier de méthode et le journal de dédoublonnage de l’archive. Chaque fiche possède un lien vers sa source Metacritic. Cet instantané documenté provient de 717 fiches individuelles et de 40 pages de classement ; il ne constitue pas un export officiel exhaustif de la base Metacritic.</p><p>Les notes sélectionnent les participants : elles n’accordent aucun point pendant le tournoi. Le vainqueur sera celui de <strong>cette communauté et de cette édition</strong>, sans prétendre à une mesure objective du meilleur jeu universel.</p><a class="text-button acid" href="https://www.metacritic.com/browse/game/" target="_blank" rel="noopener noreferrer">Consulter Metacritic ${icon('external')}</a></section><section id="equite"><span class="eyebrow acid">06 · L’ÉQUITÉ</span><h2>Une voix, un choix, par duel.</h2><p>En ligne, l’accès au vote se fait par lien envoyé à une adresse e-mail. Un compte ne peut voter qu’une fois pour un même duel, et son vote est définitif. Les résultats d’un duel en cours sont masqués tant que tu n’as pas voté. Tu peux passer un duel si tu ne connais pas suffisamment les jeux.</p><p>Vérification anti-robot, limitations de fréquence et contrôles serveur protègent le vote. Ils limitent les abus sans garantir qu’une personne ne puisse jamais utiliser plusieurs adresses e-mail. Aucun système ne peut l’affirmer ici.</p><p>Les favoris restent sur ton appareil. Les préférences de suivi n’ajoutent aucun vote. Les règles et le catalogue sont figés une fois l’édition lancée.</p></section></div></div>`;}
function profile(){const votes=Object.entries(state.myVotes);const milestone=votes.length>=100?'Gardien des légendes':votes.length>=25?'Voix de l’arène':votes.length>=5?'Challenger':'Nouvelle recrue';return `${heading('MON PARCOURS','Chaque voix laisse une trace.','Tes votes, tes favoris et les jeux que tu défends.')}<div class="profile-stats"><div>${icon('bolt')}<strong>${votes.length}</strong><span>duels votés</span></div><div>${icon('heart')}<strong>${favourites.size}</strong><span>jeux suivis</span></div><div>${icon('crown')}<strong class="badge-name">${milestone}</strong><span>ton badge de participation</span></div></div>${state.user?`<div class="account-line"><span>Connecté : ${esc(state.user.email)}</span><button class="text-button" data-action="logout">Se déconnecter</button><a class="text-button" href="/api/account/export">Exporter mes données</a><button class="text-button" data-action="delete-account">Supprimer mon compte</button></div>`:`<div class="notice">${icon('users')} Connecte-toi pour retrouver tes votes sur tes appareils. <button class="btn btn-small btn-acid" data-action="login">Me connecter</button></div>`}<h2 class="subheading">Mes jeux favoris <span class="muted-text">${favourites.size}</span></h2>${favourites.size?`<div class="favourite-list">${[...favourites].filter(id=>g(id)).map(id=>`<button class="favourite-item" data-action="game" data-id="${id}"><img src="${image(g(id))}" alt=""><span>${esc(g(id).title)}<small>${g(id).year} · ${esc(g(id).platform)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:'<div class="empty">Le cœur sur chaque jeu te permet de le suivre.<br><a href="/jeux" data-nav class="text-button acid">Découvrir les 256 jeux →</a></div>'}<h2 class="subheading">Mes derniers votes</h2>${votes.length?`<div class="history-list">${votes.reverse().slice(0,40).map(([id,game])=>`<a href="/duel/${id}" data-nav><span>${icon('check')} ${esc(g(game).title)}</span><small>${id} ${icon('arrow')}</small></a>`).join('')}</div>`:'<div class="empty">Ton premier choix t’attend dans l’arène.</div>'}`;}
function admin(){return `${heading('PILOTAGE DU TOURNOI','Les coulisses de l’arène.','Lancer l’édition, vérifier les clôtures et exporter les résultats.')}<div class="admin-panel"><form id="admin-form"><label for="admin-key">Clé administrateur</label><div class="form-row"><input id="admin-key" name="key" type="password" autocomplete="off" placeholder="ADMIN_KEY" required><button class="btn btn-acid">Ouvrir le pilotage ${icon('arrow')}</button></div></form><div id="admin-content"></div></div>`;}
function render(){if(!state)return;const active=document.activeElement?.id;const cursor=document.activeElement?.selectionStart;let content=route==='/poules'?pools():route==='/tableau'?bracket():route==='/jeux'?catalogue():route==='/propositions'?nominations():route==='/regles'?rules():route==='/profil'?profile():route==='/admin'?admin():route.startsWith('/duel/')?`${heading('LE FACE-À-FACE','Le choix t’appartient.','Les légendes se rencontrent. À toi de les départager.')}${arena()}`:home();$('#app').innerHTML=`${nav()}${state.development?'<div class="development-bar">Mode local · Votes de test</div>':''}<main id="main" class="container" tabindex="-1">${adSlot()}${content}</main>${footer()}`;localize($('#app'));$('.skip-link').textContent=tr('Aller au contenu');if(active&&$('#'+active)){const el=$('#'+active);el.focus({preventScroll:true});if(cursor!==null&&el.setSelectionRange&&el.type!=='search')el.setSelectionRange(cursor,cursor);}
  document.title=`${tr({'/jeux':'Les jeux','/poules':'Les poules','/tableau':'Le tableau','/propositions':'Propositions'}[route]||'Le tournoi des jeux cultes')} · Video Games Battle`;
}
let previousFocus;
function modal(content){previousFocus=document.activeElement;$('#modal').innerHTML=`<button class="modal-close" data-action="close-modal" aria-label="Fermer">${icon('close')}</button>${content}`;localize($('#modal'));if(!$('#modal').open)$('#modal').showModal();$('#modal .modal-close').focus();}
function closeModal(){const widget=$('#turnstile-widget');if(widget&&window.turnstile)try{window.turnstile.remove(widget);}catch{}$('#modal').close();$('#modal').innerHTML='';pendingVote=null;previousFocus?.focus?.();}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function login(){modal(`<span class="modal-symbol">${icon('bolt')}</span><div class="eyebrow acid">BIENVENUE DANS L’ARÈNE</div><h2>Les légendes ont besoin de ta voix.</h2><p>Un lien de connexion, aucun mot de passe. Une voix par duel, sur tous tes appareils.</p><form id="login-form"><label for="email">Ton adresse e-mail</label><input id="email" name="email" type="email" autocomplete="email" placeholder="toi@exemple.fr" required maxlength="254"><div id="turnstile-widget"></div><button class="btn btn-acid full-width" type="submit">Recevoir mon lien ${icon('arrow')}</button><p class="form-error" role="alert"></p></form><small>Aucun abonnement. Aucun message publicitaire. <button class="text-button" data-action="privacy">Confidentialité</button></small>${state.development?'<p class="local-note">Mode développement : le lien sera affiché ici, aucun e-mail ne sera envoyé sans configuration.</p>':''}`);mountChallenge('login');}
async function mountChallenge(action){if(!state.turnstileSiteKey)return;try{if(!window.turnstile){await new Promise((resolve,reject)=>{const existing=$('#turnstile-script');if(existing){const timer=setInterval(()=>{if(window.turnstile){clearInterval(timer);resolve();}},100);setTimeout(()=>{clearInterval(timer);reject(new Error('Vérification indisponible.'));},10000);}else{const script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=reject;document.head.append(script);}});}if($('#turnstile-widget'))window.turnstile.render('#turnstile-widget',{sitekey:state.turnstileSiteKey,action,theme:'dark'});}catch{toast('La vérification anti-robot ne se charge pas. Réessaie.');}}
function challengeToken(){return $('#turnstile-widget input[name="cf-turnstile-response"]')?.value||'';}
async function castVote(matchId,gameId,challenge=''){if(busy)return;if(!state.user){pendingVote={matchId,gameId};login();return;}if(state.turnstileSiteKey&&!challenge){pendingVote={matchId,gameId};modal(`<h2>Un dernier contrôle.</h2><p>Pour que chaque duel reste équitable.</p><form id="vote-confirm"><div id="turnstile-widget"></div><button class="btn btn-acid full-width">Confirmer mon vote ${icon('check')}</button><p class="form-error" role="alert"></p></form>`);mountChallenge('vote');return;}busy=true;document.querySelectorAll('.vote-button').forEach(b=>b.disabled=true);try{const result=await api('/api/vote',{matchId,gameId,challenge});state={...state,...result};gameMap=new Map(state.games.map(game=>[game.id,game]));selectedMatch=matchId;pendingVote=null;closeModal();render();toast('C’est enregistré. Ta voix fait partie de l’histoire.');}catch(e){if(e.status===401){state.user=null;pendingVote={matchId,gameId};login();}else toast(e.message);render();}finally{busy=false;}}
function gameDetails(id){const game=g(id);if(!game)return;const p=state.groups.find(p=>p.rows.some(r=>r.gameId===id));const matches=state.matches.filter(m=>(m.gameA===id||m.gameB===id)&&m.status==='open');modal(`<div class="game-detail-head"><img src="${image(game)}" alt="Jaquette de ${esc(game.title)}"><div><span class="eyebrow acid">SEED #${game.seed}${p?' · POULE '+String(p.id).padStart(2,'0'):''}</span><h2 data-untranslated>${esc(game.title)}</h2><p>${esc(game.platform)} · ${game.year}</p>${game.community?'<span class="acid">Choix de la communauté</span>':`<span class="detail-score">${game.score}<small>METASCORE · ${game.reviewCount} CRITIQUES</small></span>`}</div></div>${game.selectionNote?`<p class="local-note">${esc(game.selectionNote)}</p>`:''}<p>La plateforme et l’année correspondent à la version retenue pour ce tournoi.</p><div class="modal-actions"><button class="btn btn-acid" data-action="favourite" data-id="${id}">${icon('heart')} ${favourites.has(id)?'Ne plus suivre':'Suivre ce jeu'}</button><button class="btn btn-outline" data-action="card" data-id="${id}">${icon('download')} Ma carte</button></div><h3>Ses duels ouverts</h3><div class="modal-match-list">${matches.length?matches.map(m=>`<button data-action="open-match" data-id="${m.id}"><span>vs ${esc(g(m.gameA===id?m.gameB:m.gameA).title)}</span>${icon(state.myVotes[m.id]?'check':'arrow')}</button>`).join(''):'<p>Aucun duel ouvert pour le moment.</p>'}</div>${game.sourceUrl?`<a href="${esc(game.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="text-button">Voir la fiche Metacritic ${icon('external')}</a>`:''}`);}
function groupDetails(id){const p=state.groups.find(x=>x.id===Number(id));modal(`<span class="eyebrow acid">PHASE DE POULES</span><h2>Poule ${String(id).padStart(2,'0')}</h2><p>${poolMatchCount()} duels, ${state.rules.qualifyPerGroup} places en phase finale.</p><div class="modal-match-list">${state.matches.filter(m=>m.groupId===p.id).map(m=>`<button data-action="open-match" data-id="${m.id}"><span><b>${esc(short((g(m.gameA)?.title||tr('Place communautaire'))))}</b><small>vs ${esc(short((g(m.gameB)?.title||tr('Place communautaire'))))} · ${number(m.total)} votes</small></span><span class="mini-status">${state.myVotes[m.id]?icon('check'):m.status==='closed'?'Terminé':icon('arrow')}</span></button>`).join('')}</div>`);}
async function share(matchId){const m=state.matches.find(x=>x.id===matchId);const url=location.origin+(m?'/duel/'+m.id:'/');const title=m?`${(g(m.gameA)?.title||tr('Place communautaire'))} ou ${(g(m.gameB)?.title||tr('Place communautaire'))} ?`:'256 légendes. Une seule couronne.';const text=m?'J’ai mon favori. Et toi ? Vote sur Video Games Battle.':'On élit notre jeu vidéo de tous les temps. Viens défendre ta légende !';try{if(navigator.share)await navigator.share({title,text,url});else{await navigator.clipboard.writeText(`${title}\n${text}\n${url}`);toast('Lien copié. À toi de lancer le débat !');}}catch(e){if(e.name!=='AbortError')modal(`<h2>Invite tes amis.</h2><p>${esc(title)}</p><input aria-label="Lien à partager" readonly value="${esc(url)}"><p>Copie ce lien pour partager le duel.</p>`);}}
async function supporterCard(id){const game=g(id);if(!game)return;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#0b0d10';ctx.fillRect(0,0,1080,1350);const img=new Image();img.src=image(game);try{await img.decode();const scale=Math.max(920/img.width,730/img.height);ctx.save();ctx.beginPath();ctx.rect(80,230,920,730);ctx.clip();ctx.drawImage(img,540-img.width*scale/2,595-img.height*scale/2,img.width*scale,img.height*scale);ctx.restore();}catch{}const gradient=ctx.createLinearGradient(0,600,0,980);gradient.addColorStop(0,'transparent');gradient.addColorStop(1,'#0b0d10');ctx.fillStyle=gradient;ctx.fillRect(80,600,920,380);ctx.fillStyle='#d5ff3f';ctx.font='bold 34px sans-serif';ctx.fillText('VIDEO GAMES BATTLE  /  ÉDITION 01',80,105);ctx.fillStyle='#fff';ctx.font='bold 68px sans-serif';ctx.fillText('JE DÉFENDS CETTE LÉGENDE.',80,185,920);ctx.font='bold 58px sans-serif';let y=1000,line='';for(const word of game.title.split(' ')){if(ctx.measureText(line+word).width>920){ctx.fillText(line,80,y);y+=66;line='';}line+=word+' ';}ctx.fillText(line,80,y);ctx.font='28px sans-serif';ctx.fillStyle='#adb1b8';ctx.fillText(`${game.platform} · ${game.year} · Seed #${game.seed}`,80,y+62,920);ctx.fillStyle='#d5ff3f';ctx.fillRect(80,1200,920,3);ctx.font='bold 29px sans-serif';ctx.fillText('TON JEU CULTE MÉRITE SA PLACE. VOTE.',80,1260);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`je-defends-${game.id}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Ta carte supporter est prête à être partagée.');}
function privacy(){modal(`<h2>Ta voix. Tes données.</h2><p>Ton adresse e-mail sert à te connecter et à empêcher plusieurs votes du même compte sur un duel. Elle n’est jamais affichée publiquement.</p><p>Le site conserve tes votes et une session de connexion pendant 30 jours. Les adresses IP utilisées pour limiter les abus sont hachées avec un secret serveur et ne sont pas stockées en clair. Les compteurs temporaires expirent au plus tard après une heure.</p><p>Les favoris sont enregistrés uniquement dans ton navigateur. En production, Resend traite l’envoi du lien et Cloudflare Turnstile la vérification anti-robot. Les annonces directes du site sont affichées sans traceur publicitaire.</p><p>Depuis « Mon parcours », tu peux exporter tes données et supprimer ton compte. L’e-mail et les sessions sont supprimés ; les votes sont conservés sous un identifiant pseudonyme dérivé de ton e-mail avec un secret serveur, afin de préserver les résultats et d’éviter un nouveau vote après réinscription. Leurs détails sont conservés pendant l’édition et 12 mois après, puis doivent être agrégés par l’exploitant.</p>${state.contact?`<p>Contact : <a href="mailto:${esc(state.contact)}">${esc(state.contact)}</a></p>`:'<p>Avant la mise en ligne, l’exploitant doit renseigner son contact et ses mentions légales.</p>'}`);}
document.addEventListener('click',async e=>{const link=e.target.closest('a[data-nav]');if(link){e.preventDefault();const u=new URL(link.href);closeModal();navigate(u.pathname+u.search);if(u.hash)setTimeout(()=>$(u.hash)?.scrollIntoView(),20);return;}const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const {action,id,match}=button.dataset;
  try{switch(action){case'support-nomination':
    if(!state.user){login();break;}
    busy=button.disabled=true;
    try {
      const result=await api('/api/nominations/support',{id,support:button.dataset.support==='true'});
      state.nominations=result.nominations;state.games=result.games;gameMap=new Map(state.games.map(game=>[game.id,game]));render();
    } finally {busy=button.disabled=false;}
    break;
  case'login':login();break;case'profile':navigate('/profil');break;case'arena':$('#arena')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'vote':await castVote(match,id);break;case'close-modal':closeModal();break;case'next':{const m=currentMatch();if(m)skipped.add(m.id);selectedMatch=null;if(skipped.size>=state.matches.filter(m=>m.status==='open').length)skipped.clear();render();$('#arena')?.scrollIntoView({behavior:'smooth',block:'start'});break;}case'filter':filter=button.dataset.filter;selectedMatch=null;skipped.clear();render();break;case'favourite':favourites.has(id)?favourites.delete(id):favourites.add(id);localStorage.setItem('vgb-favourites',JSON.stringify([...favourites]));render();if($('#modal').open&&$('#modal .game-detail-head'))gameDetails(id);else toast(favourites.has(id)?'Ajouté à tes favoris.':'Retiré de tes favoris.');break;case'catalogue-favourites':filter=filter==='saved'?'all':'saved';render();break;case'more':gameLimit+=48;render();break;case'game':gameDetails(id);break;case'group':groupDetails(id);break;case'open-match':closeModal();navigate('/duel/'+id);break;case'bracket-tab':bracketTab=id;render();break;case'bracket-info':toast('Le vote dans le tableau s’ouvre après la clôture de toutes les poules.');break;case'seeding':navigate('/regles');$('#format')?.scrollIntoView();break;case'share':await share(match);break;case'card':await supporterCard(id);break;case'privacy':privacy();break;case'about':modal(`<span class="eyebrow acid">VIDEO GAMES BATTLE</span><h2>Le débat devient un tournoi.</h2><p>Une édition, 256 jeux, une communauté. Une invitation à redécouvrir les œuvres qui ont marqué le jeu vidéo et à en discuter ensemble.</p><p>Projet indépendant, sans affiliation à Metacritic ni aux éditeurs. Metacritic est la source des notes de sélection. Les marques et jaquettes appartiennent à leurs ayants droit.</p><a href="/regles" data-nav class="btn btn-acid">Découvrir les règles ${icon('arrow')}</a>`);break;case'logout':await api('/api/auth/logout',{});await refresh();toast('Tu es déconnecté.');break;case'dev-connect':await verifyToken(id);break;case'delete-account':modal(`<h2>Supprimer ton compte ?</h2><p>Ton adresse e-mail et tes sessions seront supprimées. Tes votes seront conservés sous un identifiant pseudonyme pour maintenir les résultats du tournoi.</p><button class="btn btn-outline" data-action="confirm-delete">Supprimer mon compte</button>`);break;case'confirm-delete':await api('/api/account/delete',{});closeModal();await refresh();toast('Compte supprimé et votes pseudonymisés.');break;case'admin-start':if(confirm(tr('Lancer les poules avec les 256 jeux ?'))){await api('/api/admin/start',{}, {Authorization:'Bearer '+adminKey});await refresh();await loadAdmin();}break;case'admin-tick':await api('/api/admin/tick',{}, {Authorization:'Bearer '+adminKey});await loadAdmin();break;case'admin-export':{const data=await api('/api/admin/results',undefined,{Authorization:'Bearer '+adminKey});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='vgb-resultats.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;gameLimit=48;render();$('#search').focus();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;render();}if(e.target.id==='language'){setLanguage(e.target.value);render();}});
document.addEventListener('submit',async e=>{
  if(e.target.id==='nomination-form'){
    e.preventDefault();
    const form=e.target;
    const button=form.querySelector('button');
    busy=button.disabled=true;
    try {
      const result=await api('/api/nominations',Object.fromEntries(new FormData(form)));
      state.nominations=result.nominations;state.games=result.games;gameMap=new Map(state.games.map(game=>[game.id,game]));render();
    } catch(error) {form.querySelector('.form-error').textContent=error.message;}
    finally {busy=button.disabled=false;}
    return;
  }
  if(e.target.id==='login-form'){e.preventDefault();const form=e.target;const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const result=await api('/api/auth/request',{email:form.email.value,locale:language(),challenge:challengeToken()});if(result.developmentToken)modal(`<span class="eyebrow acid">CONNEXION LOCALE</span><h2>Ton accès de test est prêt.</h2><p>Aucun e-mail n’a été envoyé. Ce raccourci existe uniquement en développement.</p><button class="btn btn-acid full-width" data-action="dev-connect" data-id="${result.developmentToken}">Entrer dans l’arène ${icon('arrow')}</button>`);else modal(`<span class="modal-symbol">${icon('check')}</span><h2>Regarde ta boîte mail.</h2><p>Un lien t’attend. Ouvre-le dans ce navigateur sous 15 minutes. Pense à vérifier les courriers indésirables.</p><button class="btn btn-outline" data-action="close-modal">J’ai compris</button>`);}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false;if(window.turnstile&&$('#turnstile-widget'))window.turnstile.reset();}}
  if(e.target.id==='vote-confirm'){e.preventDefault();if(pendingVote)await castVote(pendingVote.matchId,pendingVote.gameId,challengeToken());}
  if(e.target.id==='admin-form'){e.preventDefault();adminKey=e.target.key.value;e.target.key.value='';try{await loadAdmin();}catch(err){toast(err.message);}}
});
async function verifyToken(value){const requestedVote=pendingVote;await api('/api/auth/verify',{token:value});closeModal();history.replaceState({},'',location.pathname+location.search);await refresh();toast('Bienvenue dans l’arène !');if(requestedVote){await castVote(requestedVote.matchId,requestedVote.gameId);}}
async function loadAdmin(){const data=await api('/api/admin/state',undefined,{Authorization:'Bearer '+adminKey});$('#admin-content').innerHTML=`<div class="admin-summary"><p>Phase : <b>${esc(data.phase)}</b></p><p><b>${number(data.stats.votes)}</b> votes · <b>${data.stats.closed}</b> matchs clôturés · <b>${data.stats.open}</b> ouverts</p></div><div class="modal-actions">${data.phase==='setup'?'<button class="btn btn-acid" data-action="admin-start">Lancer l’édition</button>':''}<button class="btn btn-outline" data-action="admin-tick">Vérifier les clôtures</button><button class="btn btn-outline" data-action="admin-export">Exporter les résultats</button></div><h3>Derniers événements</h3><div class="admin-events">${data.audit.map(a=>`<p><time>${new Date(a.created_at).toLocaleString(language())}</time> · ${esc(a.action)}<code>${esc(a.detail)}</code></p>`).join('')}</div>`;localize($('#admin-content'));}
async function init(){try{await refresh();const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('connexion')){const value=fragment.get('connexion');history.replaceState({},'',location.pathname+location.search);try{await verifyToken(value);}catch(e){toast(e.message);login();}}}catch(e){$('#app').innerHTML=`<main class="loading"><span class="brand-mark">V</span><h1>L’arène est momentanément indisponible.</h1><p>${esc(e.message)}</p><button class="btn btn-acid" id="retry">Réessayer</button></main>`;localize($('#app'));$('#retry').onclick=init;}}
init();
setInterval(async()=>{if(document.hidden||busy||$('#modal').open||route==='/admin')return;try{const old=state;await refresh(false);if(JSON.stringify(old.stats)!==JSON.stringify(state.stats)||old.phase!==state.phase||old.games.length!==state.games.length||(route==='/propositions'&&JSON.stringify(old.nominations)!==JSON.stringify(state.nominations)))render();}catch{}},30000);
